dashboard.definition:
{
  "title": "Integrity Tech: threat overview",
  "description": "The advisory has landed. What does our environment already know about this adversary? Click a number to dig in.",
  "inputs": {
    "input_time": {
      "type": "input.timerange",
      "title": "Time",
      "options": {
        "token": "global_time",
        "defaultValue": "1789308000,1791410400"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "visualizations": {
    "viz_1": {
      "type": "splunk.singlevalue",
      "options": {
        "majorColor": "#02C8FF",
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "underLabel": "17 behaviour detections plus one finding"
      },
      "title": "Detections in this app",
      "dataSources": {
        "primary": "ds_1"
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToDashboard",
          "options": {
            "app": "integrity_tech_detections",
            "dashboard": "itd_detections",
            "newTab": false
          }
        }
      ]
    },
    "viz_2": {
      "type": "splunk.singlevalue",
      "options": {
        "majorColor": "#02C8FF",
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "underLabel": "the one that didn't is a telemetry gap"
      },
      "title": "Fired on the simulated intrusion",
      "dataSources": {
        "primary": "ds_2"
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToDashboard",
          "options": {
            "app": "integrity_tech_detections",
            "dashboard": "itd_detections",
            "newTab": false
          }
        }
      ]
    },
    "viz_3": {
      "type": "splunk.singlevalue",
      "options": {
        "majorColor": "#EB4651",
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "underLabel": "risk 100+ across 3+ tactics: open the storyline"
      },
      "title": "Entities over the risk threshold",
      "dataSources": {
        "primary": "ds_3"
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToDashboard",
          "options": {
            "app": "integrity_tech_detections",
            "dashboard": "itd_storyline",
            "newTab": false
          }
        }
      ]
    },
    "viz_4": {
      "type": "splunk.singlevalue",
      "options": {
        "majorColor": "#FF9000",
        "sparklineDisplay": "off",
        "trendDisplay": "off",
        "underLabel": "validated \u00f7 relevant behaviours: see the gaps"
      },
      "title": "Detection readiness",
      "dataSources": {
        "primary": "ds_4"
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToDashboard",
          "options": {
            "app": "integrity_tech_detections",
            "dashboard": "itd_readiness",
            "newTab": false
          }
        }
      ]
    },
    "viz_5": {
      "type": "splunk.bar",
      "options": {
        "legendDisplay": "off",
        "xAxisTitleVisibility": "hide",
        "seriesColors": [
          "#02C8FF"
        ]
      },
      "title": "Risk by entity",
      "dataSources": {
        "primary": "ds_5"
      }
    },
    "viz_6": {
      "type": "splunk.column",
      "options": {
        "legendDisplay": "bottom",
        "xAxisTitleVisibility": "hide",
        "stackMode": "stacked"
      },
      "title": "Risk added per day, by detection",
      "dataSources": {
        "primary": "ds_6"
      }
    },
    "viz_7": {
      "type": "splunk.table",
      "options": {
        "count": 10,
        "columnFormat": {
          "finding": {
            "data": "> table | seriesByName(\"finding\") | formatByType(findingFormat)",
            "rowBackgroundColors": "> table | seriesByName(\"finding\") | matchValue(findingColors)",
            "rowColors": "> table | seriesByName(\"finding\") | matchValue(findingColorsText)"
          }
        }
      },
      "title": "Entities ranked by risk (click a row to investigate)",
      "context": {
        "findingColors": [
          {
            "match": "FINDING",
            "value": "#EB4651"
          },
          {
            "match": "below threshold",
            "value": "#6B6B6B"
          }
        ],
        "findingColorsText": [
          {
            "match": "FINDING",
            "value": "#FFFFFF"
          },
          {
            "match": "below threshold",
            "value": "#FFFFFF"
          }
        ],
        "findingFormat": {
          "string": {
            "unitPosition": "after"
          }
        }
      },
      "dataSources": {
        "primary": "ds_7"
      },
      "eventHandlers": [
        {
          "type": "drilldown.linkToDashboard",
          "options": {
            "app": "integrity_tech_detections",
            "dashboard": "itd_investigate",
            "newTab": false,
            "tokens": [
              {
                "token": "entity",
                "value": "$row.entity.value$"
              }
            ]
          }
        }
      ]
    }
  },
  "dataSources": {
    "ds_1": {
      "type": "ds.search",
      "name": "Detections in this app",
      "options": {
        "query": "| rest splunk_server=local /servicesNS/-/integrity_tech_detections/saved/searches | search eai:acl.app=integrity_tech_detections title=\"AA26-281A - *\" | stats count"
      }
    },
    "ds_2": {
      "type": "ds.search",
      "name": "Fired on the simulated intrusion",
      "options": {
        "query": "| inputlookup itd_detection_catalog.csv | where type=\"Detection\" | stats count(eval(lab_rows>0)) as fired count as total | eval value=fired.\" of \".total | fields value"
      }
    },
    "ds_3": {
      "type": "ds.search",
      "name": "Entities over the risk threshold",
      "options": {
        "query": "| tstats sum(All_Risk.calculated_risk_score) as risk dc(All_Risk.annotations.mitre_attack.mitre_tactic_id) as tactics dc(source) as detections from datamodel=Risk.All_Risk where source=\"AA26-281A - *\" by All_Risk.risk_object | where risk>=100 AND tactics>=3 | stats count"
      }
    },
    "ds_4": {
      "type": "ds.search",
      "name": "Detection readiness",
      "options": {
        "query": "| inputlookup itd_readiness.csv | stats count(eval(status=\"Available\")) as ok count as total | eval value=round(100*ok/total).\"%\" | fields value"
      }
    },
    "ds_5": {
      "type": "ds.search",
      "name": "Risk by entity",
      "options": {
        "query": "| tstats sum(All_Risk.calculated_risk_score) as risk dc(All_Risk.annotations.mitre_attack.mitre_tactic_id) as tactics dc(source) as detections from datamodel=Risk.All_Risk where source=\"AA26-281A - *\" by All_Risk.risk_object | rename All_Risk.risk_object as entity | sort - risk | head 8 | table entity risk"
      }
    },
    "ds_6": {
      "type": "ds.search",
      "name": "Risk added per day, by detection",
      "options": {
        "query": "index=risk source=\"AA26-281A - *\" | eval detection=replace(source,\"^AA26-281A - (.*) - Rule$\",\"\\1\") | timechart span=1d sum(risk_score) by detection"
      }
    },
    "ds_7": {
      "type": "ds.search",
      "name": "Entities ranked by risk (click a row to investigate)",
      "options": {
        "query": "| tstats sum(All_Risk.calculated_risk_score) as risk dc(All_Risk.annotations.mitre_attack.mitre_tactic_id) as tactics dc(source) as detections from datamodel=Risk.All_Risk where source=\"AA26-281A - *\" by All_Risk.risk_object All_Risk.risk_object_type | rename All_Risk.risk_object as entity All_Risk.risk_object_type as type | eval finding=if(risk>=100 AND tactics>=3,\"FINDING\",\"below threshold\") | sort - risk | table entity type risk tactics detections finding"
      }
    }
  },
  "layout": {
    "type": "grid",
    "options": {
      "width": 1440,
      "height": 900
    },
    "structure": [
      {
        "item": "viz_1",
        "type": "block",
        "position": {
          "x": 0,
          "y": 0,
          "w": 360,
          "h": 150
        }
      },
      {
        "item": "viz_2",
        "type": "block",
        "position": {
          "x": 360,
          "y": 0,
          "w": 360,
          "h": 150
        }
      },
      {
        "item": "viz_3",
        "type": "block",
        "position": {
          "x": 720,
          "y": 0,
          "w": 360,
          "h": 150
        }
      },
      {
        "item": "viz_4",
        "type": "block",
        "position": {
          "x": 1080,
          "y": 0,
          "w": 360,
          "h": 150
        }
      },
      {
        "item": "viz_5",
        "type": "block",
        "position": {
          "x": 0,
          "y": 160,
          "w": 560,
          "h": 380
        }
      },
      {
        "item": "viz_6",
        "type": "block",
        "position": {
          "x": 560,
          "y": 160,
          "w": 880,
          "h": 380
        }
      },
      {
        "item": "viz_7",
        "type": "block",
        "position": {
          "x": 0,
          "y": 550,
          "w": 1440,
          "h": 330
        }
      }
    ],
    "globalInputs": [
      "input_time"
    ]
  }
}
